<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Database\DB;use StudPulse\Http\ApiError;use StudPulse\Integrations\DriveLibrary;use StudPulse\Security\Auth;final class Access{public static function subject(Auth$a,?string$id):?array{if(!$id){return null;}$m=$a->group();$s=DB::one('SELECT * FROM subjects WHERE id=? AND group_id=? AND term_id=?',[$id,$m['group_id'],$m['term_id']]);if(!$s){throw new ApiError(404,'NOT_FOUND','Предмет не найден');}return$s;}public static function meeting(Auth$a,?string$id,?array$scope=null):?array{if(!$id){return null;}$m=$scope??$a->group();$r=DB::one('SELECT * FROM class_meetings WHERE id=? AND group_id=? AND term_id=? AND (subgroup_id IS NULL OR subgroup_id IN (SELECT subgroup_id FROM subgroup_memberships WHERE user_id=?))',[$id,$m['group_id'],$m['term_id'],$a->user['id']]);if(!$r){throw new ApiError(404,'NOT_FOUND','Занятие не найдено');}return$r;}public static function homework(Auth$a,string$id,bool$edit=false):array{[$scope,$params]=self::homeworkScope($a);$r=DB::one("SELECT h.* FROM homework h WHERE h.id=? AND $scope AND h.deleted_at IS NULL",[$id,...$params]);if(!$r){throw new ApiError(404,'NOT_FOUND','Задание не найдено');}if($edit&&$r['author_user_id']!==$a->user['id']&&!$a->canManageGroupContent()){throw new ApiError(403,'FORBIDDEN','Редактировать может автор или староста');}return$r;}public static function homeworkScope(Auth$a):array{return['((h.group_id IS NULL AND h.term_id IS NULL AND h.author_user_id=?) OR (h.group_id=? AND h.term_id=?))',[$a->user['id'],$a->membership['group_id']??'',$a->membership['term_id']??''],];}public static function material(Auth$a,string$id,bool$edit=false):array{$r=DB::one('SELECT * FROM materials WHERE id=? AND deleted_at IS NULL',[$id]);if(!$r){throw new ApiError(404,'NOT_FOUND','Материал не найден');}if($r['visibility']==='group'){$group=LibraryGroup::selected($a->user['id']);$outsideGroup=$group!==null&&$r['group_id']!==$group;if(($outsideGroup&&(!$edit||$r['owner_user_id']!==$a->user['id']))||!DB::one('SELECT id FROM materials m WHERE m.id=? AND '.self::materialAudience('m','?'),[$id,$a->user['id']])){throw new ApiError(404,'NOT_FOUND','Материал не найден');}if(($edit&&!$r['drive_root_id'])||$r['group_id']!==($a->membership['group_id']??null))DriveLibrary::requireConnection($a);}elseif($r['owner_user_id']!==$a->user['id']){throw new ApiError(404,'NOT_FOUND','Материал не найден');}if($edit&&$r['owner_user_id']!==$a->user['id']){throw new ApiError(403,'FORBIDDEN','Действие доступно автору');}return$r;}public static function materialAudience(string$material,string$viewer):string{$group=LibraryGroup::preference('vp','vu.id');return"EXISTS(SELECT 1 FROM users vu LEFT JOIN user_preferences vp ON vp.user_id=vu.id WHERE vu.id=$viewer
            AND (($material.drive_root_id IS NULL AND NOT EXISTS(SELECT 1 FROM drive_sync_entries se WHERE se.material_id=$material.id AND se.last_direction='pull'))
                OR EXISTS(SELECT 1 FROM group_memberships verified WHERE verified.user_id=vu.id AND verified.group_id=$material.group_id
                    AND verified.term_id=$material.term_id AND verified.valid_from<=UTC_TIMESTAMP(6) AND verified.valid_to>UTC_TIMESTAMP(6)))
            AND ($material.library_variant IS NULL OR ($material.group_id=$group AND EXISTS(
                SELECT 1 FROM academic_groups vg WHERE vg.id=$material.group_id AND (
                    COALESCE(vp.preferences->>'$.subgroups.group','')<>SHA2(LOWER(TRIM(vg.canonical_code)),256)
                    OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(vp.preferences,CONCAT('$.subgroups.',$material.library_subject))),'')
                        IN ('',$material.library_variant)))))
            AND NOT EXISTS(SELECT 1 FROM material_lessons ml JOIN class_meetings cm ON cm.id=ml.meeting_id
            WHERE ml.material_id=$material.id AND (cm.group_id<>$material.group_id OR cm.term_id<>$material.term_id
            OR (cm.subgroup_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM subgroup_memberships sm
                WHERE sm.subgroup_id=cm.subgroup_id AND sm.user_id=vu.id)))))";}public static function materialReadScope(Auth$a,string$alias='m'):array{$uid=$a->user['id'];$private="($alias.visibility='private' AND $alias.owner_user_id=?)";if(!$a->membership&&!DriveLibrary::connection($a))return[$private,[$uid]];$group=LibraryGroup::selected($uid);$audience=self::materialAudience($alias,'?');$filter=$group===null?'':" AND $alias.group_id=?";return["($private OR ($alias.visibility='group'$filter AND $audience))",$group===null?[$uid,$uid]:[$uid,$group,$uid]];}public static function audit(Auth$a,string$action,string$type,string$id,string$correlation,?string$groupId=null):void{DB::run('INSERT INTO audit_events(id,actor_user_id,target_group_id,action,target_type,target_id,result,correlation_id) VALUES(?,?,?,?,?,?,?,?)',[DB::id(),$a->user['id'],$groupId??$a->membership['group_id']??null,$action,$type,$id,'success',$correlation]);}}